static void dfs(const char *s, int n, int segId, int segStart, int *segments, char **res, int *size) {
  if (segId == 4) {
    if (segStart == n) {
      char *ip = (char *)malloc(16);
      sprintf(ip, "%d.%d.%d.%d", segments[0], segments[1], segments[2], segments[3]);
      res[(*size)++] = ip;
    }
    return;
  }
  if (segStart == n) {
    return;
  }
  if (s[segStart] == '0') {
    segments[segId] = 0;
    dfs(s, n, segId + 1, segStart + 1, segments, res, size);
  }
  int addr = 0;
  for (int segEnd = segStart; segEnd < n; segEnd++) {
    addr = addr * 10 + (s[segEnd] - '0');
    if (addr > 0 && addr <= 255) {
      segments[segId] = addr;
      dfs(s, n, segId + 1, segEnd + 1, segments, res, size);
    } else {
      break;
    }
  }
}

char **restoreIpAddresses(char *s, int *returnSize) {
  int n = strlen(s);
  char **res = (char **)malloc(sizeof(char *) * 100);
  int *segments = (int *)malloc(sizeof(int) * 4);
  *returnSize = 0;
  dfs(s, n, 0, 0, segments, res, returnSize);
  free(segments);
  return res;
}

func restoreIpAddresses(s string) []string {
	n := len(s)
	res := []string{}
	segments := make([]int, 4)
	var dfs func(segId, segStart int)
	dfs = func(segId, segStart int) {
		if segId == 4 {
			if segStart == n {
				res = append(res, strconv.Itoa(segments[0])+"."+strconv.Itoa(segments[1])+"."+strconv.Itoa(segments[2])+"."+strconv.Itoa(segments[3]))
			}
			return
		}
		if segStart == n {
			return
		}
		if s[segStart] == '0' {
			segments[segId] = 0
			dfs(segId+1, segStart+1)
		}
		addr := 0
		for segEnd := segStart; segEnd < n; segEnd++ {
			addr = addr*10 + int(s[segEnd]-'0')
			if addr > 0 && addr <= 255 {
				segments[segId] = addr
				dfs(segId+1, segEnd+1)
			} else {
				break
			}
		}
	}
	dfs(0, 0)
	return res
}

class Solution {
  private static final int SEG_COUNT = 4;
  private List<String> ans = new ArrayList<>();
  private int[] segments = new int[SEG_COUNT];

  public List<String> restoreIpAddresses(String s) {
    dfs(s, 0, 0);
    return ans;
  }

  private void dfs(String s, int segId, int segStart) {
    if (segId == SEG_COUNT) {
      if (segStart == s.length()) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < SEG_COUNT; i++) {
          sb.append(segments[i]);
          if (i != SEG_COUNT - 1) {
            sb.append('.');
          }
        }
        ans.add(sb.toString());
      }
      return;
    }
    if (segStart == s.length()) {
      return;
    }
    if (s.charAt(segStart) == '0') {
      segments[segId] = 0;
      dfs(s, segId + 1, segStart + 1);
    }
    int addr = 0;
    for (int segEnd = segStart; segEnd < s.length(); segEnd++) {
      addr = addr * 10 + (s.charAt(segEnd) - '0');
      if (addr > 0 && addr <= 0xFF) {
        segments[segId] = addr;
        dfs(s, segId + 1, segEnd + 1);
      } else {
        break;
      }
    }
  }
}

class Solution:
    def restoreIpAddresses(self, s: str) -> List[str]:
        n = len(s)
        ans = []
        segments = [0] * 4

        def dfs(seg_id: int, seg_start: int):
            if seg_id == 4:
                if seg_start == n:
                    ans.append(".".join(str(x) for x in segments))
                return
            if seg_start == n:
                return
            if s[seg_start] == "0":
                segments[seg_id] = 0
                dfs(seg_id + 1, seg_start + 1)
            addr = 0
            for seg_end in range(seg_start, n):
                addr = addr * 10 + int(s[seg_end])
                if 0 < addr <= 255:
                    segments[seg_id] = addr
                    dfs(seg_id + 1, seg_end + 1)
                else:
                    break

        dfs(0, 0)
        return ans

impl Solution {
  pub fn restore_ip_addresses(s: String) -> Vec<String> {
    fn dfs(
      b: &[u8],
      seg_id: usize,
      seg_start: usize,
      segments: &mut [i32; 4],
      res: &mut Vec<String>,
    ) {
      if seg_id == 4 {
        if seg_start == b.len() {
          res.push(format!(
            "{}.{}.{}.{}",
            segments[0], segments[1], segments[2], segments[3]
          ));
        }
        return;
      }
      if seg_start == b.len() {
        return;
      }
      if b[seg_start] == b'0' {
        segments[seg_id] = 0;
        dfs(b, seg_id + 1, seg_start + 1, segments, res);
      }
      let mut addr = 0i32;
      for seg_end in seg_start..b.len() {
        addr = addr * 10 + (b[seg_end] - b'0') as i32;
        if addr > 0 && addr <= 255 {
          segments[seg_id] = addr;
          dfs(b, seg_id + 1, seg_end + 1, segments, res);
        } else {
          break;
        }
      }
    }
    let mut res = vec![];
    let mut segments = [0i32; 4];
    dfs(s.as_bytes(), 0, 0, &mut segments, &mut res);
    res
  }
}

const restoreIpAddresses = (s: string): string[] => {
  const res: string[] = [];
  const segments: number[] = new Array(4).fill(0);

  const dfs = (segId: number, segStart: number) => {
    if (segId === 4) {
      if (segStart === s.length) res.push(segments.join('.'));
      return;
    }
    if (segStart === s.length) return;
    if (s[segStart] === '0') {
      segments[segId] = 0;
      dfs(segId + 1, segStart + 1);
    }
    let addr = 0;
    for (let segEnd = segStart; segEnd < s.length; segEnd++) {
      addr = addr * 10 + (s.charCodeAt(segEnd) - 48);
      if (addr > 0 && addr <= 255) {
        segments[segId] = addr;
        dfs(segId + 1, segEnd + 1);
      } else {
        break;
      }
    }
  };

  dfs(0, 0);
  return res;
};
